// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        // owner is address(this) (deployer). Fund the contract directly.
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);

        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector));
        assertTrue(ok && address(c).balance == 0);
    }
}
